#!/usr/bin/env node
/* Corrections to the live textbook exams (src/data/textbooks/corrections.json),
 * applied on top of Dr. Cook's question banks. The nine textbook records are
 * generated by tools/import-textbooks.mjs, which applies these too, so a
 * re-import keeps them.
 *
 *   node tools/textbook-corrections.mjs           # report: applied / pending / stale
 *   node tools/textbook-corrections.mjs --write   # apply to src/content/textbooks/*.json
 *
 * Each edit sets one field (prompt / answer / accept) in one language of one
 * question (index 0-based) and records the value it replaces ("was"). An edit
 * whose question no longer holds either "was" or the new value is stale -- the
 * bank changed underneath it -- and is refused, so nothing is overwritten
 * blind. */
import fs from 'node:fs';

const FILE = 'src/data/textbooks/corrections.json';
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

export function applyCorrections(rec, edits = JSON.parse(fs.readFileSync(FILE, 'utf8')).edits) {
  const report = { applied: 0, already: 0, stale: [] };
  for (const e of edits.filter((x) => x.slug === rec.slug)) {
    const q = rec.test.questions[e.index];
    if (!q) { report.stale.push(`${e.slug} #${e.index + 1}: no such question`); continue; }
    const holder = q[e.field] ?? (q[e.field] = {});
    const cur = holder[e.lang] ?? (e.field === 'accept' ? [] : undefined);
    if (same(cur, e.new_value)) { report.already++; continue; }
    if (!same(cur, e.was)) { report.stale.push(`${e.slug} #${e.index + 1} ${e.field}.${e.lang}: expected ${JSON.stringify(e.was)}, found ${JSON.stringify(cur)}`); continue; }
    holder[e.lang] = e.new_value;
    report.applied++;
  }
  for (const q of rec.test.questions) if ((q.prompt.en.match(/____/g) || []).length !== 1 || (q.prompt.es.match(/____/g) || []).length !== 1)
    report.stale.push(`${rec.slug}: a corrected prompt does not have exactly one blank`);
  return report;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const WRITE = process.argv.includes('--write');
  const edits = JSON.parse(fs.readFileSync(FILE, 'utf8')).edits;
  let bad = 0;
  for (const slug of [...new Set(edits.map((e) => e.slug))]) {
    const f = `src/content/textbooks/${slug}.json`;
    const rec = JSON.parse(fs.readFileSync(f, 'utf8'));
    const r = applyCorrections(rec, edits);
    console.log(`${slug}: ${r.applied} to apply, ${r.already} already applied${r.stale.length ? `, ${r.stale.length} STALE` : ''}`);
    r.stale.forEach((s) => console.error('  ' + s)); bad += r.stale.length;
    if (WRITE && r.applied && !r.stale.length) fs.writeFileSync(f, JSON.stringify(rec, null, 1) + '\n');
  }
  if (bad) process.exit(1);
  if (!WRITE) console.log('report only; add --write to apply');
}
